-- Seed: payer rules extracted from verified OH/NC/SC policy documents.
--
-- Produced offline (not via the in-app ingestion pipeline) by parallel
-- Claude agents reading each source PDF, then audited by an independent
-- agent per document, then GROUNDED programmatically: every sourceQuote
-- below was checked to appear verbatim in the actual PDF text. Rules
-- whose quote could not be found were discarded, not shipped.
--
-- 79 rules kept, 0 rejected at grounding.
--
-- Fan-out: a state Medicaid policy governs every MCO in that state, so
-- one source document yields one rule per plan. payer_rule.payer_id is
-- NOT NULL, so the fan-out is explicit here.
--
-- Idempotent: deterministic UUIDs + ON CONFLICT (id) DO UPDATE.

BEGIN;

-- Source documents (one per document x payer, matching the payer-scoped dedupe).
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, extracted_at = now();

-- 249 rules, one per (payer, state, code, attribute). 40 duplicates collapsed.
ON CONFLICT (id) DO UPDATE SET
  value           = EXCLUDED.value,
  coverage_status = EXCLUDED.coverage_status,
  source_quote    = EXCLUDED.source_quote,
  confidence      = EXCLUDED.confidence,
  expiration_date = NULL;

COMMIT;

SELECT p.name AS payer, pr.state, count(*) AS rules
  FROM payer_rule pr JOIN payer p ON p.id = pr.payer_id
 WHERE pr.created_by = 'extract:payer-docs-2026-08'
 GROUP BY 1,2 ORDER BY 3 DESC, 1;
