INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('62c4e7fc-6fa4-40f4-97ac-74a35103a5af'::uuid, 'a0000000-0000-4000-8000-000000000204'::uuid, 'SC', 'medicaid_mco', '99344', 'prior_auth_required', '{"answer":"Under the Home health/home infusion category of this PAL, 99344 requires prior authorization after five visits. The first five visits may be billed without prior authorization; obtain PA before the sixth visit. No other home/residence visit codes (99341-99343, 99345, 99347-99350) appear on this list."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '2519e289-bab2-49d2-b9e3-9d2121ec99f0'::uuid, 'Prior authorization required after five visits for the following codes: 99344, 99501, 99502, 99511, 99512, S5165, S9001, S9128, S9129, S9131, T1021, T1030, T1031', 'extract:payer-docs-2026-08'),
  ('32e6c70e-8109-4a6e-92e7-2acad74fdf7c'::uuid, 'a0000000-0000-4000-8000-000000000305'::uuid, 'OH', 'medicaid_mco', '99341', 'telehealth_allowed', '{"answer":"99341 may be delivered and billed via telehealth. It is listed in the ODM \"Covered Telehealth Services\" section, in the \"Medical and Behavioral Health Services (non-OhioMHAS certified behavioral health agencies)\" procedure code table, for fee-for-service dates of service on or after January 1, 2026."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, 'db1cdade-bdc8-40f2-9431-a75835734c19'::uuid, '99341 Home or residence visit for the evaluation and management of a new patient, which requires a medically appropriate history and/or examination and straightforward medical decision making.', 'extract:payer-docs-2026-08'),
  ('7ae8b1c8-6823-4b2f-b598-44497e0383aa'::uuid, 'a0000000-0000-4000-8000-000000000306'::uuid, 'OH', 'medicaid_mco', '99341', 'telehealth_allowed', '{"answer":"99341 may be delivered and billed via telehealth. It is listed in the ODM \"Covered Telehealth Services\" section, in the \"Medical and Behavioral Health Services (non-OhioMHAS certified behavioral health agencies)\" procedure code table, for fee-for-service dates of service on or after January 1, 2026."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, '9a5de1c8-4116-4329-83f6-b354319b0327'::uuid, '99341 Home or residence visit for the evaluation and management of a new patient, which requires a medically appropriate history and/or examination and straightforward medical decision making.', 'extract:payer-docs-2026-08'),
  ('b4067b8a-296d-492d-9a24-aee355a6dc64'::uuid, 'a0000000-0000-4000-8000-000000000307'::uuid, 'OH', 'medicaid_mco', '99341', 'telehealth_allowed', '{"answer":"99341 may be delivered and billed via telehealth. It is listed in the ODM \"Covered Telehealth Services\" section, in the \"Medical and Behavioral Health Services (non-OhioMHAS certified behavioral health agencies)\" procedure code table, for fee-for-service dates of service on or after January 1, 2026."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, '3e1ff51f-df9c-4bd9-b0b6-dd3adb975b42'::uuid, '99341 Home or residence visit for the evaluation and management of a new patient, which requires a medically appropriate history and/or examination and straightforward medical decision making.', 'extract:payer-docs-2026-08'),
  ('add1787f-1d9c-4379-acd4-bb6c8abfd0bb'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99341', 'telehealth_allowed', '{"answer":"99341 may be delivered and billed via telehealth. It is listed in the ODM \"Covered Telehealth Services\" section, in the \"Medical and Behavioral Health Services (non-OhioMHAS certified behavioral health agencies)\" procedure code table, for fee-for-service dates of service on or after January 1, 2026."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, '88510853-d230-432f-ac9c-20d46b0a1b8f'::uuid, '99341 Home or residence visit for the evaluation and management of a new patient, which requires a medically appropriate history and/or examination and straightforward medical decision making.', 'extract:payer-docs-2026-08'),
  ('5010031b-a5c5-40b4-942f-bb3095e7fe30'::uuid, 'a0000000-0000-4000-8000-000000000305'::uuid, 'OH', 'medicaid_mco', '99341', 'modifier_required', '{"answer":"When 99341 is delivered through telehealth, append modifier GT to the procedure code. The document states GT is required in most cases; the stated exception is when the description of the covered procedure code in an ODM fee schedule already indicates a telehealth or electronic service."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, 'db1cdade-bdc8-40f2-9431-a75835734c19'::uuid, 'In most cases, the “GT” modifier is required to identify the service delivery through telehealth.', 'extract:payer-docs-2026-08'),
  ('c81a65b8-cf1f-446a-8e74-24c49bf3ca5d'::uuid, 'a0000000-0000-4000-8000-000000000306'::uuid, 'OH', 'medicaid_mco', '99341', 'modifier_required', '{"answer":"When 99341 is delivered through telehealth, append modifier GT to the procedure code. The document states GT is required in most cases; the stated exception is when the description of the covered procedure code in an ODM fee schedule already indicates a telehealth or electronic service."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '9a5de1c8-4116-4329-83f6-b354319b0327'::uuid, 'In most cases, the “GT” modifier is required to identify the service delivery through telehealth.', 'extract:payer-docs-2026-08'),
