  ('f338b901-b931-4819-9c0c-cbffd48a62f5'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'OH', 'commercial', '99341', 'telehealth_allowed', '{"answer":"99341 (home or residence visit, new patient, straightforward MDM) is listed in the document''s \"Service Codes Covered via Telehealth\" table, in the \"Medical and Behavioral Health Services (non ODBH certified providers)\" section. Ohio Medicaid managed care entities must cover it when delivered via telehealth."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, '2d1359cb-3a69-4d13-ad69-2936a08c236b'::uuid, 'Service Codes Covered via Telehealth', 'extract:payer-docs-2026-08'),
  ('7f3b683c-ab9b-4ee7-bc6c-c94637c4d287'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'OH', 'commercial', '99341', 'modifier_required', '{"answer":"When 99341 is delivered via telehealth and billed on a professional claim, append the GT modifier. Per the same guidance, GT is not required only if the code''s ODM fee-schedule description already indicates a telehealth or electronic service (not the case for 99341)."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '2d1359cb-3a69-4d13-ad69-2936a08c236b'::uuid, 'Telehealth Modifier GT modifier', 'extract:payer-docs-2026-08'),
  ('eea5f856-e215-49a4-8c67-038a6e38aea4'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'OH', 'commercial', '99341', 'pos_allowed', '{"answer":"On a telehealth professional claim for 99341, the place-of-service code must be the practitioner''s physical location when the service was delivered - not the patient''s location. Patient location is reported separately with the U1-U6 patient location modifiers."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '2d1359cb-3a69-4d13-ad69-2936a08c236b'::uuid, 'Physical location of the practitioner when the service was delivered', 'extract:payer-docs-2026-08'),
  ('429fc9aa-7f0f-4cf4-ad36-a1c8c89238da'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'OH', 'commercial', '99342', 'telehealth_allowed', '{"answer":"99342 (home or residence visit, new patient, low MDM) is listed in the document''s \"Service Codes Covered via Telehealth\" table, in the \"Medical and Behavioral Health Services (non ODBH certified providers)\" section. Ohio Medicaid managed care entities must cover it when delivered via telehealth."}'::jsonb, 'covered', 0.85, DATE '2026-01-01', NULL, '2d1359cb-3a69-4d13-ad69-2936a08c236b'::uuid, 'Service Codes Covered via Telehealth', 'extract:payer-docs-2026-08'),
