  ('eb137d3a-c07f-4907-af0f-7d6a5eb648a8'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid, 'NC', 'medicaid_mco', '99417', 'bundled_with', '{"answer":"When 99417 is reported, Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed on the same claim — UnitedHealthcare Community Plan treats 99358/99359 as bundled when billed alongside 99417. The Reimbursement Guidelines section lists 99417 within the group of Care Management (CM) codes that trigger this edit. Caution: the policy''s Overview section states the same edit but omits 99417 from its code list, so the two sections of this document disagree on whether 99417 is in scope; only the Reimbursement Guidelines section names it. The policy states no other rule about 99417 itself — 99417 is not included in the document''s add-on code list or in the Indiana state exception."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '6299f179-a5d6-4df0-85a7-19c222e96cbb'::uuid, 'In accordance with CMS and the AMA, Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with CM CPT codes 99417, 99484, 99487, 99489, 99490,', 'extract:payer-docs-2026-08'),
  ('deba3cc6-4e2c-4fb9-9923-9eec6ca80ac8'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99417', 'bundled_with', '{"answer":"When 99417 is reported, Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed on the same claim — UnitedHealthcare Community Plan treats 99358/99359 as bundled when billed alongside 99417. The Reimbursement Guidelines section lists 99417 within the group of Care Management (CM) codes that trigger this edit. Caution: the policy''s Overview section states the same edit but omits 99417 from its code list, so the two sections of this document disagree on whether 99417 is in scope; only the Reimbursement Guidelines section names it. The policy states no other rule about 99417 itself — 99417 is not included in the document''s add-on code list or in the Indiana state exception."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '56cd8591-87df-4b28-a86f-38fd88b4c979'::uuid, 'In accordance with CMS and the AMA, Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with CM CPT codes 99417, 99484, 99487, 99489, 99490,', 'extract:payer-docs-2026-08'),
  ('d31f57e7-cf6a-4b42-87bd-1ebaf9f6b39b'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid, 'NC', 'medicaid_mco', '99495', 'bundled_with', '{"answer":"Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed when reported with Transitional Care Management code 99495. Bill 99495 on its own; a 99358 or 99359 line submitted with it will be denied as bundled into the TCM service. This edit is stated twice in the policy (Overview and Reimbursement Guidelines), both times naming 99495."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '6299f179-a5d6-4df0-85a7-19c222e96cbb'::uuid, 'In accordance with The Centers for Medicare and Medicaid Services (CMS) and American Medical Association (AMA), Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with Care Management (CM) CPT codes 99484, 99487, 99489, 99490, 99492-99494, G2058 and Transitional Care Management (TCM) CPT codes 99495 and 99496.', 'extract:payer-docs-2026-08'),
  ('0327cd6a-2d7c-4ba6-8329-0c0167c8c539'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99495', 'bundled_with', '{"answer":"Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed when reported with Transitional Care Management code 99495. Bill 99495 on its own; a 99358 or 99359 line submitted with it will be denied as bundled into the TCM service. This edit is stated twice in the policy (Overview and Reimbursement Guidelines), both times naming 99495."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '56cd8591-87df-4b28-a86f-38fd88b4c979'::uuid, 'In accordance with The Centers for Medicare and Medicaid Services (CMS) and American Medical Association (AMA), Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with Care Management (CM) CPT codes 99484, 99487, 99489, 99490, 99492-99494, G2058 and Transitional Care Management (TCM) CPT codes 99495 and 99496.', 'extract:payer-docs-2026-08'),
  ('205c85bc-5969-4937-9952-5296eed26c77'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid, 'NC', 'medicaid_mco', '99496', 'bundled_with', '{"answer":"Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed when reported with Transitional Care Management code 99496. Bill 99496 on its own; a 99358 or 99359 line submitted with it will be denied as bundled into the TCM service. This edit is stated twice in the policy (Overview and Reimbursement Guidelines), both times naming 99496."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '6299f179-a5d6-4df0-85a7-19c222e96cbb'::uuid, 'In accordance with The Centers for Medicare and Medicaid Services (CMS) and American Medical Association (AMA), Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with Care Management (CM) CPT codes 99484, 99487, 99489, 99490, 99492-99494, G2058 and Transitional Care Management (TCM) CPT codes 99495 and 99496.', 'extract:payer-docs-2026-08'),
  ('0018a2b8-772a-43de-b93a-ff613820a1a2'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99496', 'bundled_with', '{"answer":"Prolonged Services without Direct Patient Contact (CPT 99358-99359) will not be separately reimbursed when reported with Transitional Care Management code 99496. Bill 99496 on its own; a 99358 or 99359 line submitted with it will be denied as bundled into the TCM service. This edit is stated twice in the policy (Overview and Reimbursement Guidelines), both times naming 99496."}'::jsonb, 'varies', 0.85, DATE '2026-01-01', NULL, '56cd8591-87df-4b28-a86f-38fd88b4c979'::uuid, 'In accordance with The Centers for Medicare and Medicaid Services (CMS) and American Medical Association (AMA), Prolonged Services without Direct Patient Contact (CPT codes 99358-99359) will not be separately reimbursed when reported with Care Management (CM) CPT codes 99484, 99487, 99489, 99490, 99492-99494, G2058 and Transitional Care Management (TCM) CPT codes 99495 and 99496.', 'extract:payer-docs-2026-08')
